'use strict';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={
 trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',
 briefcase:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12a22 22 0 0 0 18 0M10 13h4"/>',
 users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
 sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3ZM20 2v4M18 4h4"/>',
 orbit:'<ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(-35 12 12)"/><ellipse cx="12" cy="12" rx="4" ry="10" transform="rotate(-35 12 12)"/><circle cx="12" cy="12" r="1"/>',
 'arrow-right':'<path d="M4 12h16M14 6l6 6-6 6"/>',
 'arrow-left':'<path d="M20 12H4M10 6l-6 6 6 6"/>',
 'arrow-up-right':'<path d="M7 17 17 7M7 7h10v10"/>',
 chevrons:'<path d="m8 9 4-4 4 4M8 15l4 4 4-4"/>',
 help:'<circle cx="12" cy="12" r="9"/><path d="M9.1 9a3 3 0 0 1 5.8 1c0 2-3 2-3 4M12 17h.01"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 x:'<path d="m6 6 12 12M6 18 18 6"/>',
 upload:'<path d="M12 16V3M7 8l5-5 5 5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 code:'<path d="m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18"/>',
 layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5"/>',
 book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1ZM12 5v15"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 check:'<path d="m5 12 4 4L20 5"/>',
 'check-circle':'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 document:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6ZM14 2v6h6M8 13h8M8 17h5"/>',
 graduation:'<path d="m12 3 11 5-11 5L1 8l11-5ZM5 10v6c4 3 10 3 14 0v-6M23 8v8"/>',
 chart:'<path d="M4 3v18h17M9 16v-5M14 16V6M19 16V9"/>',
 message:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5 9 9 0 0 1-4-.9L3 21l1.9-5.5a9 9 0 0 1-.9-4A8.5 8.5 0 0 1 12.5 3H13a8.5 8.5 0 0 1 8 8v.5Z"/>',
 send:'<path d="m22 2-7 20-4-9L2 9l20-7ZM11 13 22 2"/>',
 download:'<path d="M12 3v12M7 10l5 5 5-5M4 16v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4"/>',
 copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',
 filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1V10Z"/>'
};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.document}</svg>`;}
function decorate(root=document){root.querySelectorAll('[data-icon]').forEach(node=>{node.innerHTML=icon(node.dataset.icon);});}
function initials(name){return name.split(/\s+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase();}
function tone(id){return (parseInt(id.slice(0,4),16)||0)%6;}
function avatar(candidate,extra=''){return `<span class="avatar tone-${tone(candidate.id)} ${extra}" aria-hidden="true">${esc(initials(candidate.name))}</span>`;}
function number(value){return Number(value).toLocaleString('ru-RU',{maximumFractionDigits:1});}
function plural(n,forms){return forms[n%100>=11&&n%100<=14?2:n%10===1?0:n%10>=2&&n%10<=4?1:2];}
function countLabel(n,forms){return n+' '+plural(n,forms);}
const rowLabels={full:'Полное соответствие',partial:'Частичное соответствие',none:'Нет соответствия',missing:'Не указано'};
const priorityLabels={required:'Обязательное',duty:'Задача роли',desired:'Желательное'};
const groupLabels={strong:'Высокое соответствие',partial:'Частичное соответствие',mismatch:'Есть несоответствия',unknown:'Недостаточно данных'};
function badge(group,label){return `<span class="status-badge ${group}"><i class="status-dot" aria-hidden="true"></i>${esc(label||groupLabels[group]||rowLabels[group])}</span>`;}
const state={data:null,page:'vacancies',vacancy:null,candidates:[],query:'',filter:'all',route:'',routeToken:0,
 pair:null,report:null,candidateTab:'overview',backHash:'#vacancies',drafts:{},rowFilter:'all',importKind:null,importVacancy:null,importBusy:false,
 chatId:null,chats:[],chatSending:false,chatLoadToken:0,chatDraftTimer:null,chat:[],chatDraft:'',chatBusy:false,chatJob:null,chatContext:{vacancy:null,candidate:null},history:[],pollTimer:null,toastTimer:null};
async function api(path,options={}){let r;try{r=await KadrStorage.request('/api/portal'+path,options);}catch(error){if(error?.message&&/[А-Яа-я]/.test(error.message))throw error;throw Error('Не удалось связаться с приложением. Проверьте подключение и повторите действие.');}let data;try{data=await r.json();}catch{throw Error('Не удалось получить ответ. Проверьте подключение и повторите действие.');}if(!r.ok){const error=Error(typeof data.detail==='string'?data.detail:'Проверьте заполнение полей и повторите действие.');error.status=r.status;throw error;}return data;}
function post(path,data){return api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});}
function toast(message){clearTimeout(state.toastTimer);$('toast').textContent=message;$('toast').classList.remove('hidden');state.toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),5000);}
function errorNotice(message){$('global-notice').textContent=message;$('global-notice').classList.remove('hidden');}
function hideNotice(){$('global-notice').classList.add('hidden');}
function skeleton(){return '<div class="page-loading">Готовим документы и результаты…</div>';}
function roleType(title){return /frontend|vue|html|разработ/i.test(title)?'code':/учет|учёт|основн|бухгалт/i.test(title)?'layers':'book';}
function sourceTag(source){return `<span class="source-tag">${esc(source)}</span>`;}
function excerpt(text,max=130){return text.length>max?text.slice(0,max-1)+'…':text;}
function overviewCandidate(candidate){const text=candidate.experience?.find(x=>!/^опыт работы[:\s]/i.test(x))||candidate.experience?.[0]||'Профессиональный профиль из резюме';return excerpt(text,140);}
function candidateSkills(candidate){const text=(candidate.skills||[]).join(' · ');return text.split(/\s{2,}|\u00a0+|\s*[·;]\s*/).filter(x=>x.length>3&&!/уровень/i.test(x)).slice(0,2);}
function setProfile(){const name=state.data.profile?.name||'';$('profile-name').textContent=name;$('profile-avatar').textContent=initials(name);$('nav-vacancy-count').textContent=state.data.vacancies.length;$('nav-candidate-count').textContent=state.data.candidate_count;}
function setPage(page,title){state.page=page;document.body.classList.toggle('assistant-page',page==='assistant');document.querySelectorAll('[data-nav]').forEach(n=>{n.classList.toggle('active',n.dataset.nav===page);if(n.dataset.nav===page)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});$('breadcrumb').innerHTML=`<div class="breadcrumb"><a href="#vacancies">Моё пространство</a>${icon('chevron')}<strong>${esc(title)}</strong></div>`;}
function renderTasks(){const active=state.data.tasks||[];$('task-strip').classList.toggle('hidden',!active.length);if(!active.length)return;const running=active.find(j=>j.state==='running');$('task-strip').innerHTML=`${icon('sparkles')}<span>${running?.kind==='chat'?'Готовим ответ консультанта':'Уточняем совпадения с локальным ИИ'}. Первичный разбор уже доступен.</span><details><summary>${countLabel(active.length,['задача','задачи','задач'])}</summary><div class="task-list">${active.map(j=>`<div class="task-item"><span>${j.kind==='chat'?'Вопрос консультанту':'Уточнение резюме'} · ${j.state==='running'?'в работе':'в очереди'}</span><button class="text-button" data-cancel-task="${j.id}">Остановить</button></div>`).join('')}</div></details>`;}
async function refreshWorkspace(render=true){const before=state.data?.tasks?.length||0;const previousContent=JSON.stringify([state.data?.vacancies,state.data?.closed_vacancies]);state.data=await api('/workspace');const changed=previousContent!==JSON.stringify([state.data.vacancies,state.data.closed_vacancies]);setProfile();renderTasks();if(render&&changed){if(state.page==='vacancies')renderVacancies();else if(state.page==='archive')renderArchive();else if(state.page==='vacancy'&&state.vacancy){state.vacancy=await api('/vacancies/'+state.vacancy.id);renderVacancy();}else if(state.page==='candidates'){state.candidates=await api('/candidates');renderCandidates();}}if(before&&!state.data.tasks.length&&state.pair&&$('candidate-dialog').open){const scroll=$('candidate-scroll')?.scrollTop||0;if(document.activeElement?.tagName!=='TEXTAREA'&&!$('source-dialog').open){await loadPair(state.pair.vacancy.id,state.pair.candidate.id,false);if($('candidate-scroll'))$('candidate-scroll').scrollTop=scroll;}}}
function vacancyCard(v,index){const candidates=v.candidates.slice(0,3);const strong=v.counts.strong||0;return `<article class="vacancy-card-wrap"><button class="vacancy-card" data-vacancy="${v.id}"><span class="vacancy-card-head"><span class="role-icon tone-${index%3}">${icon(roleType(v.title))}</span><span class="open-label">${v.closed?'Закрыта':'В работе'}</span></span><span class="vacancy-card-body"><h3>${esc(v.title)}</h3><p>${countLabel(v.requirement_count,['требование','требования','требований'])} к роли</p><span class="match-line"><i class="status-dot"></i>${v.closed?countLabel(v.selections?.length||0,['выбранный кандидат','выбранных кандидата','выбранных кандидатов']):strong?countLabel(strong,['сильное совпадение','сильных совпадения','сильных совпадений']):'Совпадения и вопросы по документам'}</span></span><span class="vacancy-card-footer"><span class="avatar-stack">${candidates.map(c=>avatar(c)).join('')}</span><span class="response-link">${countLabel(v.application_count,['отклик','отклика','откликов'])}${icon('arrow-up-right')}</span></span></button><button class="icon-button document-delete" data-delete-kind="vacancy" data-delete-id="${v.id}" data-delete-name="${esc(v.title)}" aria-label="Удалить вакансию ${esc(v.title)}">${icon('x')}</button></article>`;}
function renderVacancies(){setPage('vacancies','Вакансии');const data=state.data;const strong=data.vacancies.reduce((n,v)=>n+(v.counts.strong||0),0);const filtered=data.vacancies.filter(v=>v.title.toLowerCase().includes(state.query.toLowerCase()));$('page-content').innerHTML=`<div class="page-heading"><div><p class="greeting-inline">Здравствуйте, ${esc(data.profile.name)} ${icon('sparkles')}</p><h1>Ваши вакансии</h1><p class="brand-tagline">Закадри лучших в свою команду.</p></div><button class="button primary" data-import="vacancy">${icon('plus')}Добавить вакансию</button></div><div class="section-title"><div><h2>Открытые вакансии <span class="muted-count">${data.vacancies.length}</span></h2></div><label class="search-field">${icon('search')}<input id="vacancy-search" placeholder="Найти вакансию" aria-label="Найти вакансию" value="${esc(state.query)}"></label></div><div class="vacancy-grid" id="vacancy-grid">${filtered.map(v=>vacancyCard(v,data.vacancies.indexOf(v))).join('')||'<div class="empty-state"><h3>Вакансии не найдены</h3><p>Измените запрос или добавьте новую роль.</p></div>'}</div><section class="opportunity-banner"><span class="opportunity-icon">${icon('sparkles')}</span><h2>Найдите кандидату другую роль</h2><a href="#candidates" class="button secondary">Подобрать вакансию ${icon('arrow-right')}</a></section><div class="stats-row"><div class="stat"><span class="stat-icon">${icon('briefcase')}</span><div><div class="stat-value">${data.vacancies.length}</div><p class="stat-label">Вакансий в работе</p></div></div><div class="stat"><span class="stat-icon">${icon('users')}</span><div><div class="stat-value">${data.candidate_count}</div><p class="stat-label">Кандидатов в базе</p></div></div><div class="stat"><span class="stat-icon">${icon('check-circle')}</span><div><div class="stat-value">${strong}</div><p class="stat-label">Сильных совпадений</p></div></div></div>`;}
function renderArchive(){setPage('archive','Архив вакансий');const items=state.data.closed_vacancies||[];$('page-content').innerHTML=`<div class="page-heading"><div><h1>Архив вакансий</h1><p class="body-note">Завершённый подбор. Кандидаты и решения сохранены.</p></div></div><div class="vacancy-grid">${items.map(v=>vacancyCard(v,0)).join('')||'<div class="empty-state"><h3>Пока нет закрытых вакансий</h3><p>Завершите подбор кнопкой «Закрыть вакансию» внутри роли.</p></div>'}</div>`;}
function selectedPeople(v){return v.selections?.length?`<section class="selected-people"><div class="candidate-section-heading"><h2>Выбраны на роль <span class="muted-count">${v.selections.length}</span></h2><span class="selection-label">Закадрены</span></div><div class="selected-list">${v.selections.map(c=>`<div class="selected-person"><span>${c.deleted?`<strong>${esc(c.name)}</strong>`:`<button class="text-button" data-open-candidate="${c.id}" data-candidate-vacancy="${v.id}">${esc(c.name)} ${icon('arrow-up-right')}</button>`}<small>${c.deleted?'Резюме в удалённых документах':c.stage==='contacted'?'Связались · отмечено HR':'Выбран на роль'}</small></span></div>`).join('')}</div></section>`:'';}
function selectionPanel(p){const chosen=p.selection;if(!chosen&&!p.closed)return '';return `<section class="selection-panel ${chosen?'is-selected':''}"><div><strong>${chosen?'Закадрен на эту роль':'Подходит вашей команде?'}</strong><p>${p.closed?'Подбор завершён. Верните вакансию в работу, чтобы изменить выбор.':chosen?.stage==='contacted'?'Вы отметили, что связались с кандидатом.':chosen?'Кандидат в вашем списке. Можно выбрать ещё людей на эту вакансию.':'Добавьте кандидата в список выбранных на эту вакансию.'}</p></div>${p.closed?'':chosen?`<div class="selection-actions">${chosen.stage==='contacted'?'':`<button class="button secondary" data-selection-stage="contacted">Отметить: связались ${icon('check')}</button>`}<button class="text-button" data-selection-stage="remove">Убрать из выбранных</button></div>`:`<button class="button primary" data-selection-stage="selected">Закадрить ${icon('plus')}</button>`}</section>`;}
function candidateCard(c,vid){return `<button class="candidate-card" data-open-candidate="${c.id}" data-candidate-vacancy="${vid}"><span class="rank-number">${String(c.rank).padStart(2,'0')}</span>${avatar(c)}<span class="candidate-card-body"><span class="candidate-head"><h3>${esc(c.name)}</h3></span><span class="candidate-role">${esc(overviewCandidate(c))}</span><span class="candidate-characteristics"><span>${icon('clock')}<span class="characteristic-text">${esc(excerpt(c.experience_label||'Опыт описан в резюме',65))}</span></span><span>${icon('graduation')}<span class="characteristic-text">${esc(excerpt(c.education?.[0]||'Образование не указано',90))}</span></span></span><span class="candidate-tags">${candidateSkills(c).map(s=>`<span class="skill-tag">${esc(excerpt(s,55))}</span>`).join('')}</span></span><span class="candidate-score"><span class="score-number">${number(c.score)}<small>/100</small></span><span class="score-label">подтверждено</span>${badge(c.group)}<span class="open-candidate">Подробный разбор ${icon('arrow-up-right')}</span></span></button>`;}
function renderVacancy(){const v=state.vacancy;if(!v)return;setPage('vacancies',v.title);state.page='vacancy';const filtered=v.candidates.filter(c=>(state.filter==='all'||c.group===state.filter)&&c.name.toLowerCase().includes(state.query.toLowerCase()));$('page-content').innerHTML=`<div class="page-heading vacancy-page-heading"><div class="vacancy-title-row"><span class="role-icon tone-${state.data.vacancies.findIndex(item=>item.id===v.id)%3}">${icon(roleType(v.title))}</span><div><p class="eyebrow">${v.closed?'ВАКАНСИЯ ЗАКРЫТА':'ВАКАНСИЯ В РАБОТЕ'}</p><h1>${esc(v.title)}</h1><div class="sub-meta"><span>${icon('users')}${countLabel(v.application_count,['отклик','отклика','откликов'])}</span><span>${icon('document')}${v.requirement_count} требований</span><button class="text-button" data-vacancy-source>Посмотреть вакансию ${icon('arrow-up-right')}</button></div></div></div><div class="vacancy-actions">${v.closed?'':`<button class="button primary" data-import="resume" data-import-vacancy="${v.id}">${icon('plus')}Добавить отклик</button>`}<button class="button secondary" data-vacancy-state="${v.id}" data-next-closed="${!v.closed}">${v.closed?'Вернуть в работу':'Закрыть вакансию'}</button></div></div>${selectedPeople(v)}<div class="section-title"><div><h2>Кандидаты на роль</h2></div><button class="text-button" data-explain-ranking>${icon('info')}Как устроен рейтинг</button></div><div class="vacancy-toolbar"><div class="filter-pills">${[['all','Все',v.candidates.length],...Object.keys(groupLabels).map(k=>[k,{strong:'Высокое',partial:'Частично',mismatch:'Расхождения',unknown:'Мало данных'}[k],v.counts[k]])].map(([key,title,n])=>`<button class="filter-pill ${state.filter===key?'active':''}" data-filter="${key}">${esc(title)}<span>${n}</span></button>`).join('')}</div><label class="search-field">${icon('search')}<input id="candidate-search" aria-label="Найти кандидата" placeholder="Найти кандидата" value="${esc(state.query)}"></label></div><div class="candidate-list" id="candidate-list">${filtered.map(c=>candidateCard(c,v.id)).join('')||`<div class="empty-state">${icon('users')}<h3>${v.application_count?'Здесь пока нет кандидатов':'Добавьте первое резюме'}</h3><p>${v.application_count?'Попробуйте другой фильтр или имя.':'Сравним опыт с требованиями и покажем, что совпадает и что уточнить.'}</p>${!v.application_count&&!v.closed?`<button class="button primary" data-import="resume" data-import-vacancy="${v.id}">Добавить резюме</button>`:''}</div>`}</div>`;}
function renderCandidates(){
 setPage('candidates','Кандидаты');
 const filtered=state.candidates.filter(c=>c.name.toLowerCase().includes(state.query.toLowerCase()));
 $('page-content').innerHTML=`<div class="page-heading"><div><h1>Кандидаты</h1></div><button class="button primary" data-import="resume">${icon('plus')}Добавить резюме</button></div><div class="section-title"><h2>${countLabel(state.candidates.length,['кандидат','кандидата','кандидатов'])}</h2><label class="search-field">${icon('search')}<input id="pool-search" aria-label="Найти кандидата в базе" placeholder="Найти по имени" value="${esc(state.query)}"></label></div><ol class="ranked-candidates" id="candidate-pool-grid">${filtered.map(c=>`<li class="pool-row"><button class="pool-card" data-pool-candidate="${c.id}"><span class="pool-rank" aria-label="Место ${c.rank}">${String(c.rank).padStart(2,'0')}</span>${avatar(c)}<span class="pool-body"><h3>${esc(c.name)}</h3><p>${esc(excerpt(overviewCandidate(c),120))}</p><span class="pool-best"><strong>${esc(c.best_vacancy?.title||'Добавьте вакансию для сравнения')}</strong></span></span><span class="pool-score"><strong>${c.best_vacancy?number(c.best_vacancy.score):'—'}<small>${c.best_vacancy?'/100':''}</small></strong><span>Лучшее совпадение</span></span>${icon('arrow-up-right')}</button><button class="icon-button document-delete" data-delete-kind="resume" data-delete-id="${c.id}" data-delete-name="${esc(c.name)}" aria-label="Удалить кандидата ${esc(c.name)}">${icon('x')}</button></li>`).join('')||'<li class="empty-state"><h3>Кандидаты не найдены</h3><p>Измените запрос или добавьте резюме.</p></li>'}</ol>`;
}

function reportBest(){return state.report?.vacancies[0];}
async function loadPair(vid,cid,initial=true){if(!initial&&!$('candidate-dialog').open)return;const requestedRoute=location.hash;const requestToken=(state.pairToken||0)+1;state.pairToken=requestToken;const [pair,report]=await Promise.all([api(`/vacancies/${vid}/candidates/${cid}`),api(`/candidates/${cid}/vacancies`)]);if(requestedRoute!==location.hash||requestToken!==state.pairToken||(!initial&&!$('candidate-dialog').open))return;state.pair=pair;state.report=report;if(initial)state.rowFilter='all';renderCandidate();if(!$('candidate-dialog').open)$('candidate-dialog').showModal();}
function evidenceButtons(rows){return `<ul class="evidence-list">${rows.map(r=>`<li><button class="evidence-button" data-row="${esc(r.requirement_id)}">${icon(r.status==='full'?'check-circle':r.status==='missing'?'help':'info')}<span class="evidence-text">${esc(r.requirement)}<small>${r.clarification?'Полное · небольшое уточнение':rowLabels[r.status]} · посмотреть источники</small></span>${icon('arrow-up-right')}</button></li>`).join('')}</ul>`;}
function renderCandidate(){const p=state.pair;if(!p)return;const c=p.candidate,v=p.vacancy;const best=reportBest();const alternatives=state.report.vacancies.filter(item=>item.id!==v.id);const tab=state.candidateTab;const facts=p.facts;const needs=v.rows.filter(r=>r.status!=='full').sort((a,b)=>b.weight-a.weight||({none:0,missing:1,partial:2}[a.status]-{none:0,missing:1,partial:2}[b.status]));const selectedIndex=state.report.vacancies.findIndex(item=>item.id===v.id)+1;$('candidate-content').innerHTML=`<div class="candidate-content-shell"><header class="candidate-modal-header">${avatar(c)}<div class="candidate-modal-heading"><h2>${esc(c.name)}</h2><p>${esc(v.title)}</p></div><div class="candidate-modal-actions">${p.closed?'':p.selection?'<span class="selection-label">Закадрен</span>':`<button class="button primary" data-selection-stage="selected">Закадрить ${icon('plus')}</button>`}<div class="candidate-modal-score">${number(v.score)}<small>/100</small><span>подтверждено</span></div><details class="export-menu"><summary class="button secondary">${icon('download')}Для заказчика</summary><div class="export-options"><button type="button" data-download="/api/portal/candidates/${c.id}/export/html">Разбор вакансий (HTML)</button><button type="button" data-download="/api/portal/candidates/${c.id}/export/${p.has_original?'original':'txt'}">${p.has_original?'Исходный файл резюме':'Текст резюме (TXT)'}</button><button type="button" data-download="/api/portal/candidates/${c.id}/export/json">Данные сравнения (JSON)</button></div></details><button class="icon-button" data-close="candidate-dialog" aria-label="Закрыть карточку кандидата">${icon('x')}</button></div></header><div class="candidate-tabs" role="tablist" aria-label="Разбор кандидата">${[['overview','Обзор'],['vacancies','Подходящие вакансии'],['requirements','Таблица требований'],['questions','Вопросы и сообщение']].map(([key,title])=>`<button role="tab" aria-selected="${tab===key}" tabindex="${tab===key?'0':'-1'}" data-candidate-tab="${key}" class="${tab===key?'active':''}" aria-controls="candidate-tab-content">${title}</button>`).join('')}</div><div class="candidate-modal-scroll" id="candidate-scroll"><div id="candidate-tab-content" role="tabpanel">${candidateTabContent(tab,p,best,alternatives,needs,facts,selectedIndex)}</div></div></div>`;if(tab==='questions'){$('message-text').value=state.drafts[c.id+':'+v.id]??v.communication;} }
function candidateTabContent(tab,p,best,alternatives,needs,facts,selectedIndex){const c=p.candidate,v=p.vacancy;const alternativeHint=`<div class="alternative-highlight">${icon('orbit')}<div><small>${best?.id===v.id?'ЛУЧШАЯ РОЛЬ ПО ТЕКУЩИМ ДОКУМЕНТАМ':'ЕСТЬ АЛЬТЕРНАТИВНАЯ РОЛЬ'}</small><strong>${esc(best?.title||'Добавьте вакансии для сравнения')} ${best?'· '+number(best.score)+'/100':''}</strong></div><button class="text-button" data-candidate-tab="vacancies">Все ${state.report.vacancies.length} ${icon('arrow-right')}</button></div>`;
 if(tab==='overview')return `${selectionPanel(p)}${alternativeHint}<div class="detail-overview-grid"><aside><div class="profile-facts-card"><h3>Профессиональный профиль</h3>${[['experience','Опыт','briefcase'],['education','Образование','graduation'],['skills','Навыки','layers']].map(([key,label,ic])=>`<section class="fact-group"><h4>${icon(ic)}${label}</h4>${facts[key].length?facts[key].slice(0,2).map(f=>`<p>${esc(f.text)}</p>`).join(''):'<p>Не указано в резюме</p>'}</section>`).join('')}<button class="text-button" data-show-doc="resume">Открыть резюме ${icon('arrow-up-right')}</button></div></aside><div><section class="overview-section"><div class="candidate-section-heading"><h3>Что совпадает с вакансией</h3>${badge(c.group)}</div>${v.strengths.length?evidenceButtons(v.strengths.slice(0,3)):'<p>Полностью подтверждённых требований пока нет. Проверьте смежный опыт и недостающие сведения.</p>'}</section><section class="overview-section">${v.clarifications?.length?`<h3>Небольшие уточнения</h3>${evidenceButtons(v.clarifications)}`:''}<h3>Пробелы и риски: что уточнить</h3><p>Неизвестные сведения уточняем отдельно от явных противоречий.</p>${needs.length?evidenceButtons(needs.slice(0,4)):'<p>Все выделенные требования подтверждаются резюме. Проверьте ключевые навыки на встрече.</p>'}</section><div class="panel-actions"><button class="button primary" data-candidate-tab="vacancies">${icon('orbit')}Подобрать вакансию</button><button class="text-button" data-candidate-tab="questions">Подготовить вопросы ${icon('arrow-right')}</button></div><p class="detail-note">${esc(v.ranking_reason)} ${p.closed?'Вакансия закрыта.':`Среди вакансий кандидата эта роль на ${selectedIndex}-м месте.`} Индекс не является вероятностью успешной работы.</p><details class="details-summary"><summary>Как выполнен анализ</summary><p class="detail-note">${p.model.used?'Локальный ИИ уточнил '+p.model.checked_rows+' пунктов.':'Первичное сопоставление выполнено по правилам и словарю.'} ${p.model.warnings?.length?'Не все уточнения модели завершились; сохранены первичные результаты.':''} Покрытие ${number(v.coverage)}%, верхняя граница при подтверждении неизвестного ${number(v.upper)}.</p><button class="text-button" data-refine="${c.id}">Уточнить с локальным ИИ ${icon('sparkles')}</button></details></div></div>`;
 if(tab==='vacancies')return `<div class="candidate-section-heading"><h3>Подходящие вакансии</h3><button class="text-button" data-consult-candidate="${c.id}">${icon('sparkles')}Обсудить с AI</button></div><p class="body-note">Одно резюме — все вакансии. Оценка рассчитана по одинаковым правилам; откройте роль, чтобы проверить требования и причины.</p><div class="recommendation-box">${esc(state.report.recommendation)}</div><div class="vacancy-ranking">${state.report.vacancies.map(item=>`<button class="alternative-card" data-pair-vacancy="${item.id}"><span class="alternative-rank">${item.rank}</span><div><h3>${esc(item.title)}</h3><p>${esc(item.strengths.slice(0,2).map(r=>r.requirement).join(' · ')||'Недостаточно подтверждений — посмотрите вопросы и неизвестное.')}</p><p>${item.required_gaps} явных обязательных пробелов · ${item.required_unknown} не указано · покрытие ${number(item.coverage)}%</p></div><span class="score-number">${number(item.score)}<small>из 100 ${icon('arrow-up-right')}</small></span></button>`).join('')}</div><p class="detail-note">${esc(state.report.disclaimer)}</p><div class="panel-actions"><button type="button" class="button primary" data-download="/api/portal/candidates/${c.id}/export/html">${icon('download')}Сохранить разбор для заказчика</button><button type="button" class="text-button" data-download="/api/portal/candidates/${c.id}/export/${p.has_original?'original':'txt'}">${p.has_original?'Скачать исходное резюме':'Скачать текст резюме'}</button></div>`;
 if(tab==='requirements')return `<div class="detail-toolbar"><p>Все четыре статуса сохранены. Нажмите на строку, чтобы проверить исходные фрагменты вакансии и резюме.</p><select id="row-filter" aria-label="Какие требования показать">${[['all','Все требования'],['required','Только обязательные'],...Object.entries(rowLabels)].map(([key,label])=>`<option value="${key}" ${state.rowFilter===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="table-wrap"><table class="requirements-table"><thead><tr><th>Требование</th><th>Подтверждение в резюме</th><th>Статус</th><th>Комментарий</th></tr></thead><tbody>${v.rows.filter(r=>state.rowFilter==='all'||(state.rowFilter==='required'?r.priority==='required':r.status===state.rowFilter)).map(r=>`<tr data-row="${esc(r.requirement_id)}"><td><button class="requirement-link" data-row="${esc(r.requirement_id)}">${esc(r.requirement)}</button><small class="requirement-priority">${priorityLabels[r.priority]} · вес ${r.weight}</small></td><td>${r.status==='missing'?'<p>Нужных сведений не найдено.</p>':''}${r.resume_sources.length?`<span class="source-preview">«${esc(excerpt(r.resume_sources[0].quote,180))}»<small>${esc(r.resume_sources[0].document_name)}</small></span>`:'<p>Подтверждение не найдено</p>'}</td><td>${badge(r.status,r.clarification?'Полное · уточнение':rowLabels[r.status])}</td><td><p>${rowComment(r)}</p></td></tr>`).join('')||'<tr><td colspan="4">Таких требований нет. Выберите другой фильтр.</td></tr>'}</tbody></table></div>`;
 return `<div class="candidate-section-heading"><h3>Что спросить перед следующим этапом</h3><button class="text-button" data-consult-candidate="${c.id}">${icon('sparkles')}Спросить Кадр AI</button></div><ol class="interview-list">${(v.interview_questions||v.questions.map(question=>({question}))).map(q=>`<li><h4>${esc(q.question)}</h4>${q.listen_for?`<details><summary>Что проверить в ответе</summary><p>${esc(q.listen_for)}</p><p>${esc(q.follow_up)}</p><button class="text-button" data-row="${esc(q.requirement_id)}">Требование и источники ${icon('arrow-up-right')}</button></details>`:''}</li>`).join('')}</ol><details class="message-section"><summary>Подготовить сообщение кандидату</summary><p>Проверьте текст перед отправкой. Приложение не отправляет сообщения самостоятельно.</p><textarea id="message-text" rows="8" aria-label="Черновик сообщения кандидату"></textarea><button class="button secondary" id="copy-message">${icon('copy')}Скопировать сообщение</button><p id="copy-status" role="status"></p></details>`;
}
function rowComment(row){return row.comment_focus?`<span class="comment-explanation">${esc(row.comment_lead)}<strong class="comment-focus ${row.clarification?'minor':'gap'}">${esc(row.comment_focus)}</strong>${esc(row.comment_tail)}</span>`:esc(row.comment);}
function sourceBlock(source){return `<blockquote>${esc(source.quote)}</blockquote><span class="source-meta">${esc(source.document_name)} · фрагмент ${source.block_index}</span>`;}
function openSource(html,label='ПРОВЕРКА ПО ИСТОЧНИКАМ'){$('source-dialog').querySelector('.eyebrow').textContent=label;$('source-content').innerHTML=html;if(!$('source-dialog').open)$('source-dialog').showModal();}
function showRow(ident){const row=state.pair.vacancy.rows.find(r=>r.requirement_id===ident);if(!row)return;openSource(`<h2>${esc(row.requirement)}</h2>${badge(row.status,row.clarification?'Полное · небольшое уточнение':rowLabels[row.status])}<h3>Требование в вакансии</h3>${sourceBlock(row.vacancy_source)}<h3>${row.status==='missing'?'Контекст в резюме':'Подтверждение в резюме'}</h3>${row.status==='missing'?'<p>Нужных сведений не найдено. Следующие фрагменты — контекст для проверки, а не подтверждённый навык.</p>':''}${row.resume_sources.length?row.resume_sources.map(sourceBlock).join(''):'<p>Сведения не найдены. Это не доказательство отсутствия навыка.</p>'}<h3>Комментарий</h3><p>${rowComment(row)}</p><h3>Вопрос кандидату</h3><p>${esc(row.question)}</p><details><summary>Все факты резюме по разделам</summary>${Object.entries(state.pair.facts).map(([key,items])=>`<h3>${{experience:'Опыт',education:'Образование',skills:'Навыки',other:'Другие профессиональные факты'}[key]}</h3>${items.map(f=>sourceBlock(f.source)).join('')}`).join('')}</details>`);}
function explainRanking(){openSource(`<h2>Почему кандидаты расположены так</h2><p>Сначала группа высокого соответствия, затем частичного, затем явных расхождений и недостатка данных. Внутри группы — подтверждённый индекс по убыванию.</p><h3>Сводные группы карточек</h3><ul class="legend-list"><li><b>Высокое соответствие:</b> индекс не менее 75, нет явных обязательных пробелов и неизвестных обязательных требований. Отдельные пункты могут быть подтверждены частично — проверьте таблицу.</li><li><b>Частичное:</b> есть подтверждения или смежный опыт, но условия высокого соответствия не выполнены.</li><li><b>Есть несоответствия:</b> в обязательных требованиях есть явное противоречие.</li><li><b>Недостаточно данных:</b> покрытие ниже 25% либо нет положительных подтверждений, при этом нет явного обязательного противоречия.</li></ul><p>Сводная группа не заменяет четыре статуса каждого требования. Отсутствие сведений не становится отрицанием навыка.</p><h3>Рейтинг вакансий для одного кандидата</h3><p>В карточке «Подходящие вакансии» все роли сортируются по единому подтверждённому индексу. При равенстве выше роль с меньшим числом явных обязательных пробелов, затем с большим покрытием.</p><div class="formula-box">Вес обязательного пункта — 3; задачи и пожелания — 1. Полное подтверждение даёт 1. Составные пункты считаются по частям; базовое знакомство даёт половину доли инструмента. Для одного технического навыка половина веса — основа, половина — перечисленные детали. От 90% — полное с небольшим уточнением. Прочее частичное — 0,5; остальные — 0. Индекс = 100 × подтверждённый вес / полный вес. Неизвестное расширяет верхнюю границу и снижает покрытие.</div><p>Это оценка информации в документах, не вероятность успеха человека и не автоматическое решение о найме.</p>`);}
function openImport(kind,vid=null){state.importKind=kind;state.importVacancy=vid;state.importBusy=false;const resume=kind==='resume';$('import-eyebrow').textContent=resume?'НОВЫЙ КАНДИДАТ':'НОВАЯ ВОЗМОЖНОСТЬ';$('import-title').textContent=resume?(vid?'Добавить отклик':'Добавить резюме'):'Добавить вакансию';$('import-description').textContent=resume?'Прочитаем резюме и покажем, какие вакансии подходят кандидату и почему.':'Выделим требования и автоматически сопоставим роль с кандидатами из вашей базы.';$('import-name-label').textContent=resume?'Имя кандидата (необязательно)':'Название вакансии (необязательно)';$('document-name').value='';$('document-text').value='';$('import-error').classList.add('hidden');$('import-progress').classList.add('hidden');setImportTab('file');$('import-dialog').showModal();}
function setImportTab(tab){$('import-file-panel').classList.toggle('hidden',tab!=='file');$('import-text-panel').classList.toggle('hidden',tab!=='text');for(const name of ['file','text']){$('import-'+name+'-tab').classList.toggle('active',name===tab);$('import-'+name+'-tab').setAttribute('aria-selected',String(name===tab));}if(tab==='text')$('document-text').focus();}
function setImportBusy(busy,text=''){state.importBusy=busy;$('import-dialog').querySelector('[data-close]').disabled=busy;for(const id of ['select-files','save-document-text','import-file-tab','import-text-tab'])$(id).disabled=busy;$('import-progress').textContent=text;$('import-progress').classList.toggle('hidden',!busy);}
async function afterImport(results){await refreshWorkspace(false);$('import-dialog').close();const last=results[results.length-1];if(last?.kind==='vacancy'){location.hash='#vacancy/'+last.id;await renderRoute();}else if(state.importVacancy){location.hash='#vacancy/'+state.importVacancy;await renderRoute();}else{location.hash='#candidates';await renderRoute();}const duplicates=results.filter(r=>r.duplicate).length;toast(duplicates===results.length?'Документы уже есть в кабинете. Открыли сохранённые результаты.':results.some(r=>r.tasks?.length)?'Документы добавлены. Первичный разбор готов, локальный ИИ уточняет спорные пункты.':'Документы добавлены. Первичное сравнение готово.');}
async function importFiles(files){if(state.importBusy||!files.length)return;$('import-error').classList.add('hidden');setImportBusy(true,'Читаем документы и сопоставляем требования…');const results=[];try{for(const file of Array.from(files)){const form=new FormData();form.append('file',file);form.append('kind',state.importKind);if(state.importVacancy)form.append('vacancy_id',state.importVacancy);results.push(await api('/documents',{method:'POST',body:form}));}await afterImport(results);}catch(error){$('import-error').textContent=error.message;$('import-error').classList.remove('hidden');if(results.length){await refreshWorkspace();toast('Часть документов добавлена. Для остальных исправьте ошибку.');}}finally{setImportBusy(false);$('document-files').value='';}}
async function importText(event){event.preventDefault();if(state.importBusy)return;const text=$('document-text').value.trim(),name=$('document-name').value.trim();if(!text){$('import-error').textContent='Вставьте текст документа.';$('import-error').classList.remove('hidden');return;}setImportBusy(true,'Читаем текст и готовим результаты…');$('import-error').classList.add('hidden');try{const result=await post('/documents/text',{kind:state.importKind,vacancy_id:state.importVacancy,name:(name|| (state.importKind==='resume'?'Резюме':'Вакансия'))+'.txt',text:name&&!text.startsWith(name)?name+'\n'+text:text});await afterImport([result]);}catch(error){$('import-error').textContent=error.message;$('import-error').classList.remove('hidden');}finally{setImportBusy(false);}}
function chatContextText(){const v=state.data.vacancies.find(v=>v.id===state.chatContext.vacancy);const c=state.candidates.find(c=>c.id===state.chatContext.candidate)||state.pair?.candidate;return [v?.title,state.chatContext.candidate?c?.name:null].filter(Boolean).join(' · ');}
function contextSelects(){return `<label>Вакансия в контексте</label><select data-chat-scope="vacancy" aria-label="Вакансия в контексте"><option value="">Все вакансии</option>${state.data.vacancies.map(v=>`<option value="${v.id}" ${state.chatContext.vacancy===v.id?'selected':''}>${esc(v.title)}</option>`).join('')}</select><label>Кандидат в контексте</label><select data-chat-scope="candidate" aria-label="Кандидат в контексте"><option value="">Выбрать по вопросу</option>${state.candidates.map(c=>`<option value="${c.id}" ${state.chatContext.candidate===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`;}
const prompts=['Кто лучше подходит на эту вакансию?','Какие альтернативы есть для Семенова?','Какие вопросы задать кандидату?'];
function renderAssistant(){setPage('assistant','Кадр AI');$('page-content').innerHTML=`<div class="assistant-layout"><aside class="assistant-side"><h2>Контекст диалога</h2>${contextSelects()}${chatContextText()?'<button type="button" class="text-button clear-context-side" data-clear-context>Сбросить</button>':''}<div class="assistant-prompts">${prompts.map(p=>`<button data-chat-prompt="${esc(p)}">${esc(p)} ${icon('arrow-up-right')}</button>`).join('')}</div></aside><section class="chat-main"><header class="chat-titlebar"><span class="assistant-emblem">${icon('sparkles')}</span><div><h3>${esc(state.chats.find(chat=>chat.id===state.chatId)?.title||'Кадр AI')}</h3><p>HR-консультант</p></div></header><div id="chat-messages" class="chat-messages" role="log" aria-live="polite"></div><form id="chat-form" class="chat-compose"><div class="chat-compose-box"><label class="sr-only" for="chat-input">Вопрос консультанту</label><textarea id="chat-input" rows="2" maxlength="2000" placeholder="Например: какие вакансии подходят Семенову?" ${state.chatBusy?'disabled':''}></textarea><button type="button" id="chat-mic" class="chat-mic" aria-label="Продиктовать вопрос" disabled></button><button id="chat-send" aria-label="Отправить вопрос" ${state.chatBusy?'disabled':''}>${icon('send')}</button></div><div class="speech-controls"><p id="speech-status" role="status" aria-live="polite"></p><button type="button" class="record-cancel" id="chat-record-cancel" hidden>Отменить</button></div></form></section></div>`;renderChatMessages();$('chat-input').value=state.chatDraft;$('chat-form').onsubmit=sendChat;$('chat-input').onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendChat(event);}};TaktSpeech.refresh();}
function renderChatMessages(){if(!$('chat-messages'))return;const messages=state.chat.map(message=>message.role==='user'?`<div class="chat-message user">${esc(message.text)}</div>`:renderChatAnswer(message,state.chat.indexOf(message))).join('');$('chat-messages').innerHTML=messages||`<div class="chat-welcome"><div class="assistant-emblem">${icon('sparkles')}</div><h2>О чём спросим?</h2><p>Подберите вакансии кандидату или подготовьте вопросы.</p><div class="assistant-mobile-prompts">${prompts.slice(1).map(p=>`<button data-chat-prompt="${esc(p)}">${esc(p)}</button>`).join('')}</div></div>`;if(state.chatBusy)$('chat-messages').insertAdjacentHTML('beforeend',`<div class="chat-waiting"><span class="thinking-dots"><i></i><i></i><i></i></span><span id="chat-wait-text">Кадр читает вопрос и проверяет результаты…</span><button class="text-button" data-stop-chat>Остановить</button></div>`);$('chat-messages').scrollTop=$('chat-messages').scrollHeight;}
function renderChatAnswer(message,index){if(message.error)return `<div class="chat-message assistant"><p>${esc(message.text)}</p></div>`;const a=message.answer;return `<div class="chat-message assistant"><div class="assistant-label">${icon('sparkles')}Кадр AI </div>${a.blocks.map(block=>block.type==='heading'?`<h3>${esc(block.text)}</h3>`:`<p>${esc(block.text)}</p>`).join('')}<div class="chat-links">${a.links.map(link=>`<a href="${esc(link.href)}" class="chat-link">${icon(link.kind==='vacancy'?'briefcase':'users')}${esc(link.label)}${icon('arrow-up-right')}</a>`).join('')}</div><div class="answer-audio"><button type="button" data-speak-answer="${index}">Прослушать</button><button type="button" data-stop-speaking="${index}" hidden>Остановить</button></div>${a.citations.length?`<details><summary>На какие фрагменты опирается ответ (${a.citations.length})</summary>${a.citations.map(sourceBlock).join('')}</details>`:''}${a.warning?'<p class="chat-model-error">Модель недоступна — показан разбор документов.</p>':''}</div>`;}
let titleScrollAnimation=null,titleScrollButton=null;
function stopTitleScroll(){titleScrollAnimation?.cancel();titleScrollAnimation=null;titleScrollButton?.classList.remove('is-scrolling');titleScrollButton=null;}
function startTitleScroll(button){
 stopTitleScroll();if(reducedMotion())return;
 const frame=button.querySelector('.chat-title-window'),text=button.querySelector('.chat-title-scroll');if(!frame||!text)return;
 const distance=text.scrollWidth-frame.clientWidth;if(distance<=2)return;
 button.classList.add('is-scrolling');titleScrollButton=button;
 titleScrollAnimation=text.animate([{transform:'translateX(0)',offset:0},{transform:'translateX(0)',offset:.08},{transform:`translateX(-${distance}px)`,offset:.9},{transform:`translateX(-${distance}px)`,offset:1}],{duration:Math.max(3500,distance/45*1000+1200),iterations:Infinity,direction:'alternate',easing:'linear'});
}
document.addEventListener('pointerover',event=>{const button=event.target.closest('[data-chat-id]');if(button&&!button.contains(event.relatedTarget))startTitleScroll(button);});
document.addEventListener('pointerout',event=>{const button=event.target.closest('[data-chat-id]');if(button&&!button.contains(event.relatedTarget))stopTitleScroll();});
document.addEventListener('focusin',event=>{const button=event.target.closest('[data-chat-id]');if(button)startTitleScroll(button);});
document.addEventListener('focusout',event=>{if(event.target.closest('[data-chat-id]'))stopTitleScroll();});
function renderChatHistory(){
 stopTitleScroll();if(!$('chat-history-list'))return;
 $('chat-history-list').innerHTML=state.chats.map(chat=>`<li><button type="button" data-chat-id="${chat.id}" class="${state.chatId===chat.id?'active':''}" title="${esc(chat.title)}" ${state.chatId===chat.id?'aria-current="true"':''}>${icon('message')}<span class="chat-title-window"><span class="chat-title-scroll">${esc(chat.title)}</span></span></button></li>`).join('');
}
async function refreshChatHistory(){state.chats=await api('/chats');renderChatHistory();}
async function saveChatDraft(){
 clearTimeout(state.chatDraftTimer);
 if(!state.chatId||state.chatBusy)return;
 const id=state.chatId,data={draft:state.chatDraft,vacancy_id:state.chatContext.vacancy,candidate_id:state.chatContext.candidate};
 await api('/chats/'+id+'/draft',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
}
function queueChatDraft(){if(state.chatId&&!state.chatBusy)KadrStorage.stageDraft(state.chatId,{draft:state.chatDraft,vacancy_id:state.chatContext.vacancy,candidate_id:state.chatContext.candidate});clearTimeout(state.chatDraftTimer);state.chatDraftTimer=setTimeout(()=>saveChatDraft().catch(()=>toast('Черновик пока не сохранён. Проверьте соединение.')),600);}
function useChat(thread){
 try{sessionStorage.setItem('kadr.current-chat',thread.id);}catch{}
 state.chatId=thread.id;state.chat=thread.messages;state.chatDraft=thread.draft;state.chatContext=thread.context;
 state.chatBusy=Boolean(thread.pending_job);state.chatJob=thread.pending_job;
 state.history=thread.messages.filter(m=>m.role==='user').map(m=>m.text);
 renderChatHistory();if(thread.pending_job)pollChat(thread.pending_job,thread.id);
}
async function openChat(id){
 if(state.chatSending)return;document.body.classList.remove('history-open');$('toggle-chat-history').setAttribute('aria-expanded','false');
 try{
  await saveChatDraft();TaktSpeech.leave();const token=++state.chatLoadToken;
  const thread=await api('/chats/'+id);if(token!==state.chatLoadToken)return;
  useChat(thread);if(location.hash==='#assistant')renderAssistant();else location.hash='#assistant';
 }catch(error){toast(error.message);}
}
async function createChat(){
 if(state.chatSending)return;
 try{
  await saveChatDraft();TaktSpeech.leave();state.chatLoadToken++;
  const thread=await post('/chats',{});useChat(thread);await refreshChatHistory();
  if(location.hash==='#assistant')renderAssistant();else location.hash='#assistant';
 }catch(error){toast(error.message);}
}
async function sendChat(event,preset=null){
 event?.preventDefault();if(state.chatBusy||state.chatSending||TaktSpeech.active())return;
 const message=(preset??$('chat-input')?.value??'').trim();if(!message)return;
 state.chatSending=true;
 try{
  await saveChatDraft();
  if(!state.chatId){const thread=await post('/chats',{});state.chatId=thread.id;}
  const id=state.chatId;state.chatBusy=true;if(state.page==='assistant')renderAssistant();
  const job=await post('/chat',{chat_id:id,message,vacancy_id:state.chatContext.vacancy,candidate_id:state.chatContext.candidate});
  state.chat.push({role:'user',text:message});state.chatDraft='';state.chatJob=job.id;state.history.push(message);
  await refreshChatHistory();if(state.page==='assistant')renderAssistant();pollChat(job.id,id);
 }catch(error){state.chatBusy=false;state.chatDraft=message;toast(error.message);if(state.page==='assistant')renderAssistant();}
 finally{state.chatSending=false;}
}
async function pollChat(ident,chatId){
 try{
  const job=await api('/jobs/'+ident);if(state.chatId!==chatId||state.chatJob!==ident)return;
  if(['done','error','cancelled'].includes(job.state)){
   const thread=await api('/chats/'+chatId);if(state.chatId!==chatId||state.chatJob!==ident)return;
   useChat(thread);await refreshChatHistory();
   if(state.page==='assistant'){renderAssistant();$('chat-input').focus();}await refreshWorkspace(false);return;
  }
  if($('chat-wait-text'))$('chat-wait-text').textContent=job.state==='queued'?'Вопрос в очереди…':job.message.includes('Загружаем')?'Первый запуск: загружаем модель…':'Проверяем вопрос и собираем ответ…';
  setTimeout(()=>pollChat(ident,chatId),800);
 }catch(error){
  if(state.chatId!==chatId||state.chatJob!==ident)return;
  if(error.status===404){
   try{const thread=await api('/chats/'+chatId);if(state.chatId!==chatId||state.chatJob!==ident)return;useChat(thread);if(state.page==='assistant')renderAssistant();await refreshChatHistory();return;}catch{/* Retry after a transient recovery error. */}
  }
  if($('chat-wait-text'))$('chat-wait-text').textContent='Связь прервалась. Проверяем сохранённый ответ…';
  setTimeout(()=>pollChat(ident,chatId),2500);
 }
}

async function renderRoute(){if(!state.entered||!state.data?.profile)return;if(location.hash!=='#assistant')TaktSpeech.leave();const token=++state.routeToken;const next=location.hash||'#vacancies';const previous=state.route;state.route=next;hideNotice();const match=next.match(/^#vacancy\/([a-f0-9]+)(?:\/candidate\/([a-f0-9]+))?/);const candidateRoute=next.match(/^#candidate\/([a-f0-9]+)(?:\/vacancy\/([a-f0-9]+))?/);try{if(match){const vid=match[1],cid=match[2];if(!cid){state.filter='all';state.query='';if($('candidate-dialog').open)$('candidate-dialog').close();}if(!state.vacancy||state.vacancy.id!==vid){$('page-content').innerHTML=skeleton();state.query='';state.filter='all';}const vacancy=await api('/vacancies/'+vid);if(token!==state.routeToken)return;state.vacancy=vacancy;renderVacancy();if(cid){if(!/candidate\//.test(previous))state.backHash=previous||'#vacancy/'+vid;state.candidateTab='overview';await loadPair(vid,cid);}}else if(candidateRoute){const cid=candidateRoute[1];if(!/candidate\//.test(previous))state.backHash=previous||'#candidates';const report=await api('/candidates/'+cid+'/vacancies');if(token!==state.routeToken)return;const vid=candidateRoute[2]||report.vacancies[0]?.id;if(!vid){toast('Добавьте вакансию, чтобы увидеть сравнение.');return;}state.candidateTab='vacancies';await loadPair(vid,cid);}else{if($('candidate-dialog').open)$('candidate-dialog').close();state.query='';state.filter='all';if(next==='#assistant'){state.candidates=await api('/candidates');if(!state.chatId&&state.chats.length){let selected=null;try{selected=sessionStorage.getItem('kadr.current-chat');}catch{}const id=state.chats.some(chat=>chat.id===selected)?selected:state.chats[0].id;const thread=await api('/chats/'+id);if(token!==state.routeToken)return;useChat(thread);}if(token!==state.routeToken)return;renderAssistant();}else if(next==='#candidates'){setPage('candidates','Кандидаты');$('page-content').innerHTML=skeleton();const candidates=await api('/candidates');if(token!==state.routeToken)return;state.candidates=candidates;renderCandidates();}else if(next==='#archive')renderArchive();else renderVacancies();}window.scrollTo({top:0,behavior:'instant'});}catch(error){errorNotice(error.message);}}
function askDelete(kind,id,name){
 state.deletionTarget={kind,id,name};$('delete-title').textContent=kind==='resume'?'Удалить кандидата?':'Удалить вакансию?';
 $('delete-name').textContent=name;$('delete-error').classList.add('hidden');$('confirm-delete').disabled=false;$('delete-dialog').showModal();
}
async function showDeleted(){
 const items=await api('/documents/deleted');
 openSource(`<h2>Удалённые документы</h2>${items.length?`<ul class="deleted-list">${items.map(item=>`<li><span><small>${item.kind==='resume'?'Кандидат':'Вакансия'}</small><strong>${esc(item.name)}</strong></span><button class="button secondary" data-restore-id="${item.id}" data-restore-kind="${item.kind}">Восстановить</button></li>`).join('')}</ul>`:'<p>Здесь пока пусто.</p>'}`,'КОРЗИНА');
}
async function refreshAfterDeletion(){
 state.pairToken=(state.pairToken||0)+1;state.pair=null;state.report=null;state.vacancy=null;
 state.chatContext={vacancy:null,candidate:null};
 if($('candidate-dialog').open)$('candidate-dialog').close();
 const destination=state.page==='candidates'?'#candidates':'#vacancies';history.replaceState(null,'',destination);
 await refreshWorkspace(false);state.candidates=await api('/candidates');await renderRoute();
}
$('confirm-delete').onclick=async()=>{
 const target=state.deletionTarget;if(!target)return;$('confirm-delete').disabled=true;
 try{await api('/documents/'+target.kind+'/'+target.id,{method:'DELETE'});$('delete-dialog').close();await refreshAfterDeletion();toast(target.kind==='resume'?'Кандидат удалён':'Вакансия удалена');}
 catch(error){$('delete-error').textContent=error.message;$('delete-error').classList.remove('hidden');}
 finally{$('confirm-delete').disabled=false;}
};
$('deleted-documents').onclick=()=>showDeleted().catch(error=>toast(error.message));
function changeCandidateTab(tab){const scroll=$('candidate-scroll')?.scrollTop||0;state.candidateTab=tab;renderCandidate();const button=$('candidate-content').querySelector(`[data-candidate-tab="${tab}"][role="tab"]`);button?.focus({preventScroll:true});if($('candidate-scroll'))$('candidate-scroll').scrollTop=tab==='requirements'?0:0;}
function openContext(){openSource(`<h2>О чём спросить консультанта</h2><p>Можно выбрать вакансию и кандидата или указать их в самом вопросе.</p><div class="context-fields">${contextSelects()}</div><button class="button primary" data-close="source-dialog">Готово ${icon('check')}</button>`);}
function openHelp(){openSource(`<h2>Ваше пространство подбора</h2><h3>1. Откройте вакансию</h3><p>Внутри уже есть учебные отклики. Сводные карточки показывают совпадения, индекс и статус. Добавить свои документы можно из файла или текста.</p><h3>2. Найдите подходящую роль для человека</h3><p>В карточке кандидата откройте «Подходящие вакансии». Здесь все роли упорядочены по одной формуле и есть рекомендация. Откройте роль для подробной таблицы четырёх статусов.</p><h3>3. Проверьте основания и подготовьте разговор</h3><p>В каждой паре есть требования, цитаты, комментарии, сильные стороны, риски и вопросы. Разбор и текст резюме можно сохранить для рассмотрения заказчиком.</p><h3>4. Спросите Кадр AI</h3><p>Локальная модель понимает вопрос. Ответ собирается из результатов и сопровождается внутренними ссылками. Модель не выдумывает новые цитаты и не отправляет сообщения.</p><h3>Где сохраняются данные</h3><p>В хранилище этого браузера. При обработке данные временно передаются на сервер приложения. Ваш кабинет сохраняется в этом браузере; у другого посетителя будет свой. Учебные примеры не означают реальные отклики; «Подбор из базы» означает автоматически предложенную связь.</p><button class="button secondary" data-explain-ranking>Как устроена оценка ${icon('chart')}</button>`);}
const SESSION_NAME_KEY='kadr.session-name';
function sessionName(){try{return sessionStorage.getItem(SESSION_NAME_KEY)||'';}catch{return '';}}
function rememberName(name){try{if(name)sessionStorage.setItem(SESSION_NAME_KEY,name);else sessionStorage.removeItem(SESSION_NAME_KEY);}catch{/* A fresh page can simply ask again when storage is unavailable. */}}
const reducedMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const motionWait=milliseconds=>new Promise(resolve=>setTimeout(resolve,reducedMotion()?0:milliseconds));
async function showOnboarding(){
 clearTimeout(state.pollTimer);document.body.classList.remove('assistant-page');state.entered=false;state.data.profile=null;
 $('app').classList.add('hidden');$('app').classList.remove('workspace-enter');
 $('greeting').classList.add('hidden');$('greeting').classList.remove('greeting-leave');
 const intro=$('onboarding');intro.classList.remove('hidden','intro-leave','intro-ready');
 $('hr-name').value='';$('name-error').classList.add('hidden');
 await new Promise(requestAnimationFrame);intro.classList.add('intro-ready');
 setTimeout(()=>{if(!state.entered&&!intro.classList.contains('hidden'))$('hr-name').focus({preventScroll:true});},reducedMotion()?0:750);
}
async function enter(name,animate=true){
 state.data.profile={name};rememberName(name);
 if(animate){
  $('onboarding').classList.add('intro-leave');await motionWait(320);
  $('onboarding').classList.add('hidden');$('onboarding').classList.remove('intro-leave');
  $('greeting-text').textContent='Здравствуйте, '+name;
  $('greeting').classList.remove('hidden','greeting-leave');await motionWait(1150);
  history.replaceState(null,'','#vacancies');
 }else $('onboarding').classList.add('hidden');
 state.entered=true;setProfile();renderTasks();await refreshChatHistory();await renderRoute();
 $('app').classList.remove('hidden');
 if(animate){
  $('app').classList.add('workspace-enter');$('greeting').classList.add('greeting-leave');
  await motionWait(500);$('greeting').classList.add('hidden');await motionWait(900);$('app').classList.remove('workspace-enter');
 }
 startRefresh();
}

function startRefresh(){clearTimeout(state.pollTimer);state.pollTimer=setTimeout(async()=>{try{if(!state.importBusy)await refreshWorkspace(!$('candidate-dialog').open&&state.page!=='assistant'&&document.activeElement?.tagName!=='INPUT');}catch{/* Keep the current workspace visible while a transient connection recovers. */}startRefresh();},state.data.tasks?.length?3500:20000);}
// UI actions are delegated so replaced panels retain keyboard-native buttons.
document.addEventListener('click',async event=>{const target=event.target.closest('button,a,[data-row]');if(!target)return;try{if(target.dataset.download){await KadrStorage.download(target.dataset.download);return;}if(target.dataset.selectionStage){target.disabled=true;try{const p=state.pair;const scroll=$('candidate-scroll').scrollTop;await api(`/vacancies/${p.vacancy.id}/selections/${p.candidate.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({stage:target.dataset.selectionStage})});await refreshWorkspace(false);await loadPair(p.vacancy.id,p.candidate.id,false);if($('candidate-scroll'))$('candidate-scroll').scrollTop=scroll;if(!$('candidate-dialog').open)await renderRoute();else $('candidate-content').querySelector('[data-selection-stage]')?.focus({preventScroll:true});toast(target.dataset.selectionStage==='selected'?'Кандидат закадрен':target.dataset.selectionStage==='contacted'?'Отметка о связи сохранена':'Кандидат убран из выбранных');}finally{target.disabled=false;}return;}if(target.dataset.vacancyState){const v=state.vacancy;const close=target.dataset.nextClosed==='true';openSource(`<h2>${close?'Закрыть вакансию?':'Вернуть вакансию в работу?'}</h2><p><strong>${esc(v.title)}</strong></p><p>${close?`Вакансия перейдёт в архив. Выбранных кандидатов: ${v.selections.length}. Можно вернуться к подбору позже.`:'Вакансия снова появится в подборе. Выбранные кандидаты сохранятся.'}</p><div class="delete-actions"><button class="button secondary" data-close="source-dialog">Отмена</button><button class="button primary" data-confirm-vacancy-state="${v.id}" data-next-closed="${close}">${close?'Закрыть и перенести в архив':'Вернуть в работу'}</button></div>`,'ПОДБОР');return;}if(target.dataset.confirmVacancyState){target.disabled=true;try{const closed=target.dataset.nextClosed==='true';await api('/vacancies/'+target.dataset.confirmVacancyState+'/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({closed})});$('source-dialog').close();state.vacancy=null;await refreshWorkspace(false);location.hash=closed?'#archive':'#vacancy/'+target.dataset.confirmVacancyState;await renderRoute();toast(closed?'Вакансия сохранена в архиве':'Вакансия снова в работе');}finally{target.disabled=false;}return;}if(target.dataset.deleteId){askDelete(target.dataset.deleteKind,target.dataset.deleteId,target.dataset.deleteName);return;}if(target.dataset.restoreId){await post('/documents/'+target.dataset.restoreKind+'/'+target.dataset.restoreId+'/restore',{});state.vacancy=null;await refreshWorkspace(false);state.candidates=await api('/candidates');await renderRoute();await showDeleted();toast('Документ восстановлен');return;}if(target.dataset.chatId){openChat(target.dataset.chatId);return;}if(target.dataset.close){if(target.dataset.close==='import-dialog'&&state.importBusy)return;$(target.dataset.close).close();return;}if(target.dataset.import){openImport(target.dataset.import,target.dataset.importVacancy||null);return;}if(target.dataset.vacancy){location.hash='#vacancy/'+target.dataset.vacancy;return;}if(target.dataset.openCandidate){location.hash=`#vacancy/${target.dataset.candidateVacancy}/candidate/${target.dataset.openCandidate}`;return;}if(target.dataset.poolCandidate){location.hash='#candidate/'+target.dataset.poolCandidate;return;}if(target.dataset.pairVacancy){location.hash=`#vacancy/${target.dataset.pairVacancy}/candidate/${state.pair.candidate.id}`;return;}if(target.dataset.candidateTab){changeCandidateTab(target.dataset.candidateTab);return;}if(target.dataset.row){showRow(target.dataset.row);return;}if(target.dataset.showDoc){const document=target.dataset.showDoc==='resume'?state.pair.resume_document:state.pair.vacancy_document;openSource(`<h2>${esc(document.name)}</h2><pre class="source-full">${esc(document.text)}</pre>`);return;}if(target.hasAttribute('data-vacancy-source')){openSource(`<h2>${esc(state.vacancy.title)}</h2><pre class="source-full">${esc(state.vacancy.document.text)}</pre>`);return;}if(target.dataset.filter){state.filter=target.dataset.filter;renderVacancy();return;}if(target.hasAttribute('data-explain-ranking')){explainRanking();return;}if(target.dataset.refine){await post('/candidates/'+target.dataset.refine+'/refine');toast('Локальный ИИ уточнит спорные пункты. Результат сохранится в кабинете.');await refreshWorkspace(false);return;}if(target.dataset.consultCandidate){state.chatContext={candidate:target.dataset.consultCandidate,vacancy:state.pair.vacancy.id};$('candidate-dialog').close();location.hash='#assistant';return;}if(target.hasAttribute('data-chat-context')){openContext();return;}if(target.hasAttribute('data-clear-context')){event.preventDefault();state.chatContext={vacancy:null,candidate:null};queueChatDraft();renderAssistant();return;}if(target.dataset.chatPrompt){if(state.page!=='assistant'){location.hash='#assistant';return;}sendChat(null,target.dataset.chatPrompt);return;}if(target.hasAttribute('data-stop-chat')){if(state.chatJob)await post('/jobs/'+state.chatJob+'/cancel');return;}if(target.dataset.cancelTask){await post('/jobs/'+target.dataset.cancelTask+'/cancel');await refreshWorkspace(false);return;}if(target.id==='copy-message'){const text=$('message-text').value;try{await navigator.clipboard.writeText(text);$('copy-status').textContent='Сообщение скопировано. Можно вставить его в почту или мессенджер.';}catch{$('message-text').focus();$('message-text').select();$('copy-status').textContent='Нажмите Ctrl+C (на Mac — ⌘C), чтобы скопировать выделенный текст.';}return;}}catch(error){if($('source-dialog').open)toast(error.message);else if($('candidate-dialog').open)toast(error.message);else errorNotice(error.message);}});
document.addEventListener('change',event=>{const target=event.target;if(target.id==='row-filter'){state.rowFilter=target.value;renderCandidate();$('row-filter').focus();}if(target.dataset.chatScope){state.chatContext[target.dataset.chatScope]=target.value||null;queueChatDraft();document.querySelectorAll(`[data-chat-scope="${target.dataset.chatScope}"]`).forEach(select=>select.value=target.value);if(state.page==='assistant'&&!$('source-dialog').open)renderAssistant();}});
document.addEventListener('input',event=>{const target=event.target;if(target.id==='chat-input'){state.chatDraft=target.value;queueChatDraft();}if(target.id==='message-text'&&state.pair){const key=state.pair.candidate.id+':'+state.pair.vacancy.id;state.drafts[key]=target.value;KadrStorage.saveMessageDraft(key,target.value);}if(['vacancy-search','candidate-search','pool-search'].includes(target.id)){state.query=target.value;const position=target.selectionStart;const id=target.id;if(id==='vacancy-search')renderVacancies();else if(id==='candidate-search')renderVacancy();else renderCandidates();$(id).focus({preventScroll:true});$(id).setSelectionRange(position,position);}});
document.addEventListener('keydown',event=>{const tab=event.target.closest('[data-candidate-tab][role="tab"]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const names=['overview','vacancies','requirements','questions'];const index=names.indexOf(tab.dataset.candidateTab);changeCandidateTab(event.key==='Home'?names[0]:event.key==='End'?names[3]:names[(index+(event.key==='ArrowRight'?1:3))%4]);}});
// Dismiss only a complete click on the backdrop, never a drag from dossier content.
let candidateBackdropPress=false;
function outsideCandidate(event){const bounds=$('candidate-dialog').getBoundingClientRect();return event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom;}
$('candidate-dialog').addEventListener('pointerdown',event=>{candidateBackdropPress=event.isPrimary&&event.button===0&&event.target===$('candidate-dialog')&&outsideCandidate(event);});
$('candidate-dialog').addEventListener('pointercancel',()=>{candidateBackdropPress=false;});
$('candidate-dialog').addEventListener('click',event=>{
 const dismiss=candidateBackdropPress&&event.detail>0&&event.target===$('candidate-dialog')&&outsideCandidate(event)&&!$('source-dialog').open;
 candidateBackdropPress=false;if(dismiss){event.preventDefault();event.stopPropagation();$('candidate-dialog').close();}
});
$('candidate-dialog').addEventListener('close',()=>{candidateBackdropPress=false;});
$('candidate-dialog').addEventListener('close',()=>{if(/candidate\//.test(location.hash))location.hash=state.backHash||'#vacancies';});
$('source-dialog').addEventListener('close',()=>{if(state.page==='assistant')renderAssistant();});
$('import-dialog').addEventListener('cancel',event=>{if(state.importBusy)event.preventDefault();});
$('new-chat').onclick=()=>{document.body.classList.remove('history-open');$('toggle-chat-history').setAttribute('aria-expanded','false');createChat();};
$('toggle-chat-history').onclick=()=>{$('toggle-chat-history').setAttribute('aria-expanded',String(document.body.classList.toggle('history-open')));};
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.body.classList.remove('history-open');$('toggle-chat-history').setAttribute('aria-expanded','false');}});
$('help-button').onclick=openHelp;
$('profile-button').onclick=()=>{$('profile-edit-name').value=state.data.profile.name;$('profile-error').classList.add('hidden');$('profile-dialog').showModal();};
$('profile-form').onsubmit=async event=>{event.preventDefault();try{const profile=await api('/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('profile-edit-name').value})});state.data.profile=profile;rememberName(profile.name);setProfile();$('profile-dialog').close();toast('Имя сохранено.');if(state.page==='vacancies')renderVacancies();}catch(error){$('profile-error').textContent=error.message;$('profile-error').classList.remove('hidden');}};
$('restart-intro').onclick=async()=>{TaktSpeech.leave();rememberName('');state.routeToken++;for(const id of ['profile-dialog','source-dialog','candidate-dialog','import-dialog'])if($(id).open)$(id).close();history.replaceState(null,'','#vacancies');await showOnboarding();};
$('name-form').onsubmit=async event=>{event.preventDefault();$('enter-workspace').disabled=true;$('name-error').classList.add('hidden');try{const profile=await api('/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('hr-name').value})});await enter(profile.name);}catch(error){$('name-error').textContent=error.message;$('name-error').classList.remove('hidden');}finally{$('enter-workspace').disabled=false;}};
$('import-file-tab').onclick=()=>setImportTab('file');$('import-text-tab').onclick=()=>setImportTab('text');$('select-files').onclick=()=>$('document-files').click();$('document-files').onchange=event=>importFiles(event.target.files);$('import-text-panel').onsubmit=importText;
$('drop-zone').ondragover=event=>{event.preventDefault();if(!state.importBusy)$('drop-zone').classList.add('drag-over');};$('drop-zone').ondragleave=()=>$('drop-zone').classList.remove('drag-over');$('drop-zone').ondrop=event=>{event.preventDefault();$('drop-zone').classList.remove('drag-over');importFiles(event.dataTransfer.files);};window.addEventListener('dragover',event=>event.preventDefault());window.addEventListener('drop',event=>event.preventDefault());
window.addEventListener('hashchange',renderRoute);
window.addEventListener('pagehide',()=>{if(state.chatId&&!state.chatBusy)KadrStorage.stageDraft(state.chatId,{draft:state.chatDraft,vacancy_id:state.chatContext.vacancy,candidate_id:state.chatContext.candidate});});
window.addEventListener('kadr-storage-error',event=>errorNotice(event.detail));
TaktSpeech.init({busy:()=>state.chatBusy,draft:()=>state.chatDraft,setDraft:text=>{state.chatDraft=text;queueChatDraft();},answerText:index=>{const message=state.chat[index];return message?.answer?.blocks.map(block=>block.text).join('\n\n')||message?.text||'';}});
(async()=>{
 const began=performance.now();decorate();$('onboard-symbol').innerHTML=icon('sparkles');$('enter-arrow').innerHTML=icon('arrow-right');
 try{
  await KadrStorage.init();state.drafts=await KadrStorage.messageDrafts();state.data=await api('/workspace');const name=sessionName();
  await motionWait(Math.max(0,420-(performance.now()-began)));
  if(name){if(!state.data.profile)await api('/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});await enter(name,false);}else await showOnboarding();
  $('boot').classList.add('boot-leave');await motionWait(280);$('boot').classList.add('hidden');
 }catch(error){
  $('boot').innerHTML=`<img src="/static/assets/kadr-mark.svg" alt="Кадр" width="50" height="50"><p>${esc(error.message)}</p><button class="button primary" id="retry-boot">Попробовать снова</button>`;$('retry-boot').onclick=()=>location.reload();
 }
})();
